-- Etapa 6C. Compra 2017; UF do pedido SP; todos os status. Executar READ ONLY.
SELECT 'fato_pedidos' fato,(SELECT count(*) FROM gold.fato_pedidos) origem,count(*) apos_joins,count(DISTINCT (x.order_id)) graos,count(*) FILTER(WHERE d0.cliente_sk IS NULL OR d1.localizacao_sk IS NULL OR d2.data_sk IS NULL OR d3.data_sk IS NULL OR d4.data_sk IS NULL OR d5.data_sk IS NULL OR d6.data_sk IS NULL) fk_ausente FROM gold.fato_pedidos x LEFT JOIN gold.dim_clientes d0 ON d0.cliente_sk=x.cliente_sk LEFT JOIN gold.dim_localizacao d1 ON d1.localizacao_sk=x.localizacao_sk LEFT JOIN gold.dim_calendario d2 ON d2.data_sk=x.data_compra_sk LEFT JOIN gold.dim_calendario d3 ON d3.data_sk=x.data_aprovacao_sk LEFT JOIN gold.dim_calendario d4 ON d4.data_sk=x.data_transportadora_sk LEFT JOIN gold.dim_calendario d5 ON d5.data_sk=x.data_entrega_sk LEFT JOIN gold.dim_calendario d6 ON d6.data_sk=x.data_previsao_entrega_sk UNION ALL SELECT 'fato_itens_pedido' fato,(SELECT count(*) FROM gold.fato_itens_pedido) origem,count(*) apos_joins,count(DISTINCT (x.order_id,x.order_item_id)) graos,count(*) FILTER(WHERE d0.cliente_sk IS NULL OR d1.localizacao_sk IS NULL OR d2.produto_sk IS NULL OR d3.vendedor_sk IS NULL OR d4.data_sk IS NULL OR d5.data_sk IS NULL) fk_ausente FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_clientes d0 ON d0.cliente_sk=x.cliente_sk LEFT JOIN gold.dim_localizacao d1 ON d1.localizacao_sk=x.localizacao_sk LEFT JOIN gold.dim_produtos d2 ON d2.produto_sk=x.produto_sk LEFT JOIN gold.dim_vendedores d3 ON d3.vendedor_sk=x.vendedor_sk LEFT JOIN gold.dim_calendario d4 ON d4.data_sk=x.data_compra_sk LEFT JOIN gold.dim_calendario d5 ON d5.data_sk=x.data_limite_envio_sk UNION ALL SELECT 'fato_pagamentos' fato,(SELECT count(*) FROM gold.fato_pagamentos) origem,count(*) apos_joins,count(DISTINCT (x.order_id,x.payment_sequential)) graos,count(*) FILTER(WHERE d0.cliente_sk IS NULL OR d1.localizacao_sk IS NULL OR d2.forma_pagamento_sk IS NULL OR d3.data_sk IS NULL) fk_ausente FROM gold.fato_pagamentos x LEFT JOIN gold.dim_clientes d0 ON d0.cliente_sk=x.cliente_sk LEFT JOIN gold.dim_localizacao d1 ON d1.localizacao_sk=x.localizacao_sk LEFT JOIN gold.dim_forma_pagamento d2 ON d2.forma_pagamento_sk=x.forma_pagamento_sk LEFT JOIN gold.dim_calendario d3 ON d3.data_sk=x.data_compra_sk;
